mapper.select:
select stock_id, item_type, item_id, product_id, shop_dept_id,
       warehouse_id, current_quantity, locked_quantity,
       available_quantity, quarantine_quantity, cost_price,
       total_cost, version
from inv_stock
where shop_dept_id = #{fact.targetWarehouseId}
  and warehouse_id = #{fact.targetWarehouseId}
  and item_type = #{fact.itemType}
  and item_id = #{fact.itemId}
for update

select rs.receipt_serial_id, rs.receipt_id,
       rs.receipt_allocation_id, rs.shipment_id,
       rs.shipment_allocation_id, rs.serial_id,
       rs.serial_no_snapshot, serial.serial_no as current_serial_no,
       rs.disposition, serial.item_type, serial.item_id,
       serial.warehouse_id as current_warehouse_id,
       serial.balance_id as current_balance_id,
       serial.lot_id as current_lot_id,
       serial.location_id as current_location_id,
       rs.status_after as receipt_status_after,
       serial.serial_status as current_status
from inv_transfer_shipment_receipt_serial rs
inner join inv_inventory_serial serial
        on serial.serial_id = rs.serial_id
       and serial.item_type = #{fact.itemType}
       and serial.item_id = #{fact.itemId}
where rs.receipt_allocation_id = #{fact.receiptAllocationId}
  and rs.receipt_id = #{fact.receiptId}
  and rs.shipment_id = #{fact.shipmentId}
  and rs.shipment_allocation_id = #{fact.shipmentAllocationId}
  and rs.disposition = 'damaged'
  and rs.status_after = 'quarantine'
  and serial.warehouse_id = #{fact.targetWarehouseId}
  and serial.balance_id = #{fact.damagedTargetBalanceId}
  and serial.lot_id = #{fact.damagedTargetLotId}
  and serial.location_id = #{fact.quarantineLocationId}
  and serial.serial_status = 'quarantine'
  and not exists (
      select 1
      from inv_transfer_receipt_discrepancy_damage_loss_serial used
      where used.receipt_serial_id = rs.receipt_serial_id
         or used.serial_id = rs.serial_id
  )
order by rs.receipt_serial_id, serial.serial_id
for update

mapper.update:
update inv_stock
set current_quantity = #{effect.stockCurrentAfter},
    quarantine_quantity = #{effect.stockQuarantineAfter},
    total_cost = #{effect.stockTotalCostAfter},
    cost_price = #{effect.stockCostPriceAfter},
    version = #{effect.stockVersionAfter},
    last_out_time = #{effect.execution.executedAt},
    update_by = #{effect.execution.executorName},
    update_time = sysdate()
where stock_id = #{effect.stockId}
  and shop_dept_id = #{effect.fact.targetWarehouseId}
  and warehouse_id = #{effect.fact.targetWarehouseId}
  and item_type = #{effect.fact.itemType}
  and item_id = #{effect.fact.itemId}
  and version = #{effect.stockVersionBefore}
  and current_quantity = #{effect.stockCurrentBefore}
  and available_quantity = #{effect.stockAvailableQuantity}
  and locked_quantity = #{effect.stockLockedQuantity}
  and quarantine_quantity = #{effect.stockQuarantineBefore}
  and total_cost = #{effect.stockTotalCostBefore}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{effect.stockCurrentAfter} = current_quantity
      - #{effect.quantity}
  and #{effect.stockQuarantineAfter} = quarantine_quantity
      - #{effect.quantity}
  and #{effect.stockTotalCostAfter} = total_cost - #{effect.amount}
  and #{effect.stockVersionAfter} = version + 1
  and current_quantity >= #{effect.quantity}
  and quarantine_quantity >= #{effect.quantity}
  and total_cost >= #{effect.amount}

update inv_stock_balance_detail
set current_quantity = #{effect.balanceCurrentAfter},
    quarantine_quantity = #{effect.balanceQuarantineAfter},
    total_cost = #{effect.balanceTotalCostAfter},
    cost_price = #{effect.balanceCostPriceAfter},
    version = #{effect.balanceVersionAfter},
    last_out_time = #{effect.execution.executedAt},
    update_by = #{effect.execution.executorName},
    update_time = sysdate()
where balance_id = #{effect.balanceId}
  and warehouse_id = #{effect.fact.targetWarehouseId}
  and item_type = #{effect.fact.itemType}
  and item_id = #{effect.fact.itemId}
  and lot_id = #{effect.fact.damagedTargetLotId}
  and location_id = #{effect.fact.quarantineLocationId}
  and version = #{effect.balanceVersionBefore}
  and current_quantity = #{effect.balanceCurrentBefore}
  and available_quantity = #{effect.balanceAvailableQuantity}
  and available_quantity = 0
  and locked_quantity = #{effect.balanceLockedQuantity}
  and quarantine_quantity = #{effect.balanceQuarantineBefore}
  and total_cost = #{effect.balanceTotalCostBefore}
  and current_quantity = available_quantity + locked_quantity
      + quarantine_quantity
  and #{effect.balanceCurrentAfter} = current_quantity
      - #{effect.quantity}
  and #{effect.balanceQuarantineAfter} = quarantine_quantity
      - #{effect.quantity}
  and #{effect.balanceTotalCostAfter} = total_cost - #{effect.amount}
  and #{effect.balanceVersionAfter} = version + 1
  and current_quantity >= #{effect.quantity}
  and quarantine_quantity >= #{effect.quantity}
  and total_cost >= #{effect.amount}

update inv_inventory_serial
set serial_status = 'scrapped',
    update_by = #{effect.execution.executorName},
    update_time = sysdate(),
    remark = concat('adjudication damage write-off action=',
            #{effect.execution.actionId})
where serial_id = #{serial.serialId}
  and serial_no = #{serial.serialNo}
  and item_type = #{effect.fact.itemType}
  and item_id = #{effect.fact.itemId}
  and warehouse_id = #{effect.fact.targetWarehouseId}
  and balance_id = #{effect.fact.damagedTargetBalanceId}
  and lot_id = #{effect.fact.damagedTargetLotId}
  and location_id = #{effect.fact.quarantineLocationId}
  and serial_status = 'quarantine'

mapper.insert:
insert into inv_transfer_receipt_discrepancy_damage_loss_serial (
    damage_loss_ledger_id, request_id, adjudication_action_id,
    receipt_serial_id, serial_id, serial_no_snapshot,
    warehouse_id, balance_id, lot_id, location_id,
    status_before, status_after, create_by, create_time
)
select loss.damage_loss_ledger_id, loss.request_id,
       loss.adjudication_action_id, rs.receipt_serial_id,
       rs.serial_id, rs.serial_no_snapshot,
       #{effect.fact.targetWarehouseId},
       #{effect.fact.damagedTargetBalanceId},
       #{effect.fact.damagedTargetLotId},
       #{effect.fact.quarantineLocationId},
       'quarantine', 'scrapped',
       #{effect.execution.executorName}, sysdate()
from inv_transfer_receipt_discrepancy_damage_loss_ledger loss
inner join inv_transfer_shipment_receipt_serial rs
        on rs.receipt_serial_id = #{serial.receiptSerialId}
       and rs.serial_id = #{serial.serialId}
       and rs.serial_no_snapshot = #{serial.serialNo}
       and rs.receipt_id = #{effect.fact.receiptId}
       and rs.receipt_allocation_id =
           #{effect.fact.receiptAllocationId}
       and rs.shipment_id = #{effect.fact.shipmentId}
       and rs.shipment_allocation_id =
           #{effect.fact.shipmentAllocationId}
       and rs.disposition = 'damaged'
       and rs.status_after = 'quarantine'
inner join inv_inventory_serial serial_current
        on serial_current.serial_id = rs.serial_id
       and serial_current.serial_no = rs.serial_no_snapshot
       and serial_current.item_type = #{effect.fact.itemType}
       and serial_current.item_id = #{effect.fact.itemId}
       and serial_current.warehouse_id =
           #{effect.fact.targetWarehouseId}
       and serial_current.balance_id =
           #{effect.fact.damagedTargetBalanceId}
       and serial_current.lot_id =
           #{effect.fact.damagedTargetLotId}
       and serial_current.location_id =
           #{effect.fact.quarantineLocationId}
       and serial_current.serial_status = 'scrapped'
where loss.request_id = #{effect.execution.requestId}
  and loss.adjudication_action_id =
      #{effect.execution.actionId}
  and loss.action_version_before =
      #{effect.execution.executionVersionBefore}
  and not exists (
      select 1
      from inv_transfer_receipt_discrepancy_damage_loss_serial prior
      where prior.receipt_serial_id = #{serial.receiptSerialId}
         or prior.serial_id = #{serial.serialId}
  )
